def arm_full(q,start):
 T=np.eye(4)
 for i,a in zip(range(start,start+4),q):T=T@trans(axes[i]/np.linalg.norm(axes[i]),points[i],a)
 E=np.eye(4);E[:3,3]=points[start+3];return T@E
qa0=np.array([0,3.11,0,1.49,0,-3.11,0,1.49]);Ta0=[arm_full(qa0[:4],11),arm_full(qa0[4:],15)]
low=np.r_[[-2,-2,-2,-3.14,-3.14], np.array(s['qpos']['range'])[11:,0]];high=np.r_[[2,2,2,3.14,3.14],np.array(s['qpos']['range'])[11:,1]]
def solve_full(theta,prev=None):
 v0=np.r_[np.zeros(5),qa0] if prev is None else prev
 def fun(v):
  B=np.eye(4);B[:3,3]=v[:3];B[:3,:3]=Rot.from_euler('zyx',[v[4],theta,v[3]]).as_matrix()
  errs=[]
  for k,start in enumerate([11,15]):
