"""High bar controller using only the Robot API, joint sensors, and pelvis IMU."""
import json
from pathlib import Path
import numpy as np
from rcb_client import Robot
from PIL import Image

r=Robot()
s=r.spec()
limits=np.asarray(s['qpos']['range'],float)
def action(q):
 return np.clip(2*(np.asarray(q)-limits[:,0])/(limits[:,1]-limits[:,0])-1,-1,1).tolist()
def pose(h=0,k=0,p=0,roll=3.11,yaw=0,e=1.49):
 return np.array([0,0,h,k,0,0,0,h,k,0,0,p,roll,yaw,e,p,-roll,-yaw,e],float)

def main():
 obs=r.observe(images=False)
 if obs['done'] or obs['step']>0:obs=r.reset(images=False)
 wf=0.;direction=1;last=-35;stage=0;count=0;h=0.;log=[]
 for i in range(1000):
  g=np.array(obs['imu']['gravity']);w=np.array(obs['imu']['gyro']);wf=.95*wf+.05*w[1]
  if stage==0:
   if i-last>35 and wf*direction<-.15:direction=-direction;last=i
   h=0 if direction==1 else -2.8
   if i<10:h=-2
   q=pose(h=h,p=-1.5*direction,yaw=-.6*direction,e=2.61 if direction==1 else -1.25)
   if g[2]>.5:
    stage=1;count=0
    print('Capture',i,g,w,flush=True)
  else:
   h=min(0,h+.08)
   k=1.5 if h<-.7 else max(0,1.5-(h+.7)*3)
   q=pose(h=h,k=k,p=0,roll=0,yaw=np.pi,e=1.49)
   q[0]=.4;q[5]=-.4
